const std = @import("std");

fn extractName(comptime json: []const u8) []const u8 {
    comptime {
        const start = 8;
        var end = start;
        while (end < json.len and json[end] != '"') end += 1;
        return json[start..end];
    }
}

pub fn main() !void {
    const json = "{\"name\":\"Zig\",\"year\":2024}";
    const name = comptime extractName(json);
    std.debug.print("Extracted: {s}\n", .{name});
}

